from pwn import remote
import binascii

def get_cookie(username):
    r = remote('crypto.chal.csaw.io', 8000)
    r.recvuntil(b'> ')
    r.sendline(b'1')
    r.recvuntil(b': ')
    r.sendline(username.encode())
    out = r.recvline().decode()
    r.close()
    if 'cookie:' in out:
        return out.split('cookie:')[1].strip()
    return None

def main():
    usernames = ['', 'aaaa', 'aaaaa', 'aaaaaa', 'flag']
    cookies = {}
    for user in usernames:
        c = get_cookie(user)
        print(f"username: {user:8}, cookie: {c}")
        cookies[user] = c
    # Split cookies into 32 hex-char blocks
    blks = {user: [cookies[user][i:i+32] for i in range(0, len(cookies[user]), 32)]
            for user in cookies if cookies[user]}
    print("\nCookie blocks per username:")
    for user, blocks in blks.items():
        print(f"{user:8} : {blocks}")
    # Compare all 'flag' blocks to all other blocks
    flag_blocks = blks['flag']
    matches = []
    for idx, fb in enumerate(flag_blocks):
        for uname in ('', 'aaaa', 'aaaaa', 'aaaaaa'):
            if uname not in blks: continue
            for jdx, b in enumerate(blks[uname]):
                if fb == b:
                    matches.append((idx, uname, jdx))
    print(f"\nMatches for flag blocks in other cookies:")
    for m in matches:
        print(f"flag block {m[0]} matches {m[1]} block {m[2]}")
    # Attempt to craft user for full-flag
    # Naively try all combinations/permutations, and block-repetitions (simple CBC bit-flipping redundancy?)
    from itertools import product
    basics = ['', 'aaaa', 'aaaaa', 'aaaaaa']
    nblocks = len(flag_blocks)
    found = False
    print('\nTrying to craft username block permutations:')
    attempts = list(product(basics, repeat=nblocks))
    for a in attempts:
        possible_user = ''.join(a)
        c = get_cookie(possible_user)
        if c == cookies['flag']:
            print(f"Success: username '{possible_user}' reproduces flag cookie!")
            found = True
            break
    print('\nChecking ASCII in flag blocks:')
    for idx, fb in enumerate(flag_blocks):
        try:
            decoded = binascii.unhexlify(fb)
            if b'flag{' in decoded or any([65 <= b <= 128 for b in decoded]):
                print(f"flag block {idx}: {decoded}")
        except:
            pass
    print('\nDone.')

if __name__ == '__main__':
    main()

from pwn import *
import re

HOST = 'crypto.chal.csaw.io'
PORT = 8000

def get_cookie(username):
    p = remote(HOST, PORT)
    p.recvuntil(b': ')
    p.sendline(username.encode())
    out = p.recvline()
    m = re.search(rb'([0-9a-f]{64})', out)
    cookie = m.group(1).decode() if m else None
    p.close()
    return cookie

def split_blocks(hexstr, sz=32):
    return [hexstr[i:i+sz] for i in range(0, len(hexstr), sz)]

